    55  /*  m must be a string, like  "DWARFSTRINGERR..."  for this to work */
    56  #define DWSERR(m) dwarfstring_append_length(data,(m),sizeof(m)-1)
    57
    58  static unsigned long minimumnewlen = 30;
    59  /*
    60  struct dwarfstring_s {
    61     char *        s_data;
    62     unsigned long s_size;
    63     unsigned long s_avail;
    64     unsigned char s_malloc;
    65  };
    66  */
    67
    68  int
    69  dwarfstring_constructor(struct dwarfstring_s *g)
    70  {
    71      g->s_data = "";
    72      g->s_size = 0;
    73      g->s_avail = 0;
    74      g->s_malloc = FALSE;
    75      return TRUE;
    76  }
    77
    78  static int
    79  dwarfstring_resize_to(struct dwarfstring_s *g,unsigned long newlen)
    80  {
    81      char *b = 0;
    82      unsigned long lastpos =
    83          g->s_size - g->s_avail;
    84      unsigned long malloclen = newlen+1;
    85
    86      if (malloclen < minimumnewlen) {
    87          malloclen = minimumnewlen;
    88      }
    89      b = malloc(malloclen);
    90      if (!b) {
    91          return FALSE;
    92      }
    93      if (lastpos > 0) {
    94          memcpy(b,g->s_data,lastpos);
    95      }
    96      if (g->s_malloc) {
    97          free(g->s_data);
    98          g->s_data = 0;
    99      }
   100      g->s_data = b;
   101      g->s_data[lastpos] = 0;
   102      g->s_size = newlen;
   103      g->s_avail = newlen - lastpos;
   104      g->s_malloc = TRUE;
   105      return TRUE;
   106  }
   107
   108  int
   109  dwarfstring_reset(struct dwarfstring_s *g)
   110  {
   111      if (!g->s_size) {
   112          /* In initial condition, nothing to do. */
   113          return TRUE;
   114      }
   115      g->s_avail = g->s_size;
   116      g->s_data[0] = 0;
   117      return TRUE;
   118  }
   119
   120  int
   121  dwarfstring_constructor_fixed(struct dwarfstring_s *g,
   122      unsigned long len)
   123  {
   124      int r = FALSE;
   125
   126      dwarfstring_constructor(g);
   127      if (len == 0) {
   128          return TRUE;
   129      }
   130      r = dwarfstring_resize_to(g,len);
   131      if (!r) {
   132          return FALSE;
   133      }
   134      return TRUE;
   135  }
   136
   137  int
   138  dwarfstring_constructor_static(struct dwarfstring_s *g,
   139      char * space,
   140      unsigned long len)
   141  {
   142      dwarfstring_constructor(g);
   143      g->s_data = space;
   144      g->s_data[0] = 0;
   145      g->s_size = len;
   146      g->s_avail = len;
   147      g->s_malloc = FALSE;
   148      return TRUE;
   149  }
   150
   151  void
   152  dwarfstring_destructor(struct dwarfstring_s *g)
   153  {
   154      if (g->s_malloc) {
   155          free(g->s_data);
   156          g->s_data = 0;
   157          g->s_malloc = 0;
   158      }
   159      dwarfstring_constructor(g);
   160  }
