   162  /*  For the case where one wants just the first 'len'
   163      characters of 'str'. NUL terminator provided
   164      for you in s_data.
   165  */
   166  int
   167  dwarfstring_append_length(struct dwarfstring_s *g,char *str,
   168      unsigned long slen)
   169  {
   170      unsigned long lastpos = g->s_size - g->s_avail;
   171      int r = 0;
   172
   173      if (!str  || slen ==0) {
   174          return TRUE;
   175      }
   176      if (slen >= g->s_avail) {
   177          unsigned long newlen = 0;
   178
   179          newlen = g->s_size + slen+2;
   180          r = dwarfstring_resize_to(g,newlen);
   181          if (!r) {
   182              /* Unable to resize, dare not do anything. */
   183              return FALSE;
   184          }
   185      }
   186      memcpy(g->s_data + lastpos,str,slen);
   187      g->s_avail -= slen;
   188      g->s_data[g->s_size - g->s_avail] = 0;
   189      return TRUE;
   190  }
   191
   192  int
   193  dwarfstring_append(struct dwarfstring_s *g,char *str)
   194  {
   195      unsigned long dlen = 0;
   196
   197      if (!str) {
   198          return TRUE;
   199      }
   200      dlen = strlen(str);
   201      return dwarfstring_append_length(g,str,dlen);
   202  }
   203
   204  char *
   205  dwarfstring_string(struct dwarfstring_s *g)
   206  {
   207      return g->s_data;
   208  }
   209
   210  unsigned long
   211  dwarfstring_strlen(struct dwarfstring_s *g)
   212  {
   213      return g->s_size - g->s_avail;
   214  }
