   216  static int
   217  _dwarfstring_append_spaces(dwarfstring *data,
   218      size_t count)
   219  {
   220      int res = 0;
   221      char spacebuf[] = {"                                       "};
   222      size_t charct = sizeof(spacebuf)-1;
   223      size_t l = count;
   224
   225      while (l > charct) {
   226          res = dwarfstring_append_length(data,spacebuf,charct);
   227          l -= charct;
   228          if (res != TRUE) {
   229              return res;
   230          }
   231      }
   232      /* ASSERT: l > 0 */
   233      res = dwarfstring_append_length(data,spacebuf,l);
   234      return res;
   235  }
   236  static int
   237  _dwarfstring_append_zeros(dwarfstring *data, size_t l)
   238  {
   239      int res = 0;
   240      static char zeros[] = {
   241          "0000000000000000000000000000000000000000"};
   242      size_t charct = sizeof(zeros)-1;
   243
   244      while (l > charct) {
   245          res = dwarfstring_append_length(data,zeros,charct);
   246          l -= charct;
   247          if (res != TRUE) {
   248              return res;
   249          }
   250      }
   251      /* ASSERT: l > 0 */
   252      dwarfstring_append_length(data,zeros,l);
   253      return res;
   254  }
